/* ==HELPERS== */
function mk(w,h){ const c=document.createElement('canvas'); c.width=w; c.height=h; const g=c.getContext('2d'); g.imageSmoothingEnabled=false; return [c,g]; }
let _seed = 20260921;
function rnd(){ _seed = (_seed*1664525 + 1013904223)>>>0; return _seed/4294967296; }
function ri(a,b){ return a + Math.floor(rnd()*(b-a+1)); }
function px(g,c,x,y,w,h){ g.fillStyle=c; g.fillRect(x|0,y|0,w||1,h||1); }
function disc(g,c,cx,cy,r){ g.fillStyle=c; for(let y=-r;y<=r;y++){ const s=Math.floor(Math.sqrt(r*r-y*y)); g.fillRect(cx-s,cy+y,s*2+1,1); } }
function sprite(rows,pal){ const [c,g]=mk(rows[0].length,rows.length);
  rows.forEach((r,y)=>{ for(let x=0;x<r.length;x++){ const k=pal[r[x]]; if(k){ g.fillStyle=k; g.fillRect(x,y,1,1);} } }); return c; }
function flipH(c){ const [f,g]=mk(c.width,c.height); g.translate(c.width,0); g.scale(-1,1); g.drawImage(c,0,0); return f; }
const clamp=(v,a,b)=>v<a?a:v>b?b:v;

const C = {
  ink:'#07110c', leaf9:'#06150f', leaf8:'#0b2318', leaf7:'#103424', leaf6:'#17482f', leaf5:'#1f6b45', leaf4:'#2f8a57', leaf3:'#58b57c', leaf2:'#9ad9a0',
  pap:'#ff8a3d', papD:'#e2612a', papDD:'#a83f1c', papL:'#ffc08a',
  ivo:'#fbf3df', ivoD:'#d9cfb2', ivoDD:'#a59c80',
  stone:'#8f9a7e', stoneD:'#66735a', stoneDD:'#3b4638', stoneL:'#bcc5a4',
  dirt:'#4a3323', dirtD:'#2f2016', dirtL:'#6b4a30',
  water:'#1c7a72', waterD:'#0f4f50', waterL:'#7fe0c6',
  wood:'#9a6a35', woodD:'#5a3520'
};

/* ==TILES== */
const TILE = {};
(function makeTiles(){
  // temple stone brick, 3 variants
  TILE.brick = [0,1,2].map(v=>{ const [c,g]=mk(T,T); px(g,C.stone,0,0,T,T);
    for(let r=0;r<2;r++){ const y=r*8;
      px(g,C.stoneL,0,y,T,1); px(g,C.stoneD,0,y+6,T,1); px(g,C.stoneDD,0,y+7,T,1);
      const vx=(r*8+v*5+3)%16; px(g,C.stoneDD,vx,y,1,7); px(g,C.stoneL,(vx+1)%16,y+1,1,5); }
    for(let i=0;i<7;i++) px(g, rnd()<.5?C.stoneD:C.stoneL, ri(1,14), ri(1,14));
    if(v===2){ for(let i=0;i<5;i++) px(g,C.leaf5,ri(0,13),ri(2,13),ri(1,3),1); }
    return c; });
  // moss cap drawn over exposed brick tops
  TILE.moss = [0,1].map(()=>{ const [c,g]=mk(T,T); px(g,C.leaf5,0,0,T,2); px(g,C.leaf3,0,0,T,1);
    for(let x=0;x<T;x++){ const d=ri(0,3); if(d) px(g,C.leaf5,x,2,1,d); if(rnd()<.2) px(g,C.leaf2,x,0); if(d===3) px(g,C.leaf6,x,4); }
    return c; });
  // jungle earth + grass cap
  TILE.earth = [0,1].map(()=>{ const [c,g]=mk(T,T); px(g,C.dirt,0,0,T,T);
    for(let i=0;i<10;i++) px(g, rnd()<.6?C.dirtD:C.dirtL, ri(0,14), ri(0,15), ri(1,2), 1);
    px(g,C.ivoDD,ri(2,12),ri(5,12),2,1); return c; });
  TILE.grass = [0,1].map(()=>{ const [c,g]=mk(T,T); px(g,C.leaf4,0,0,T,3); px(g,C.leaf3,0,0,T,1);
    for(let x=0;x<T;x++){ const d=ri(1,4); px(g,C.leaf5,x,3,1,d); if(rnd()<.3) px(g,C.leaf2,x,0); if(rnd()<.25) px(g,C.leaf6,x,3+d); }
    return c; });
  // dark temple back wall + column
  TILE.wall = [0,1,2].map(v=>{ const [c,g]=mk(T,T); px(g,C.leaf8,0,0,T,T);
    for(let r=0;r<2;r++){ const y=r*8; px(g,C.leaf7,0,y,T,1); px(g,C.ink,0,y+7,T,1); px(g,C.ink,(r*8+v*6+2)%16,y,1,7); }
    if(v===1) px(g,C.leaf6,ri(2,10),ri(2,12),3,1); if(v===2){ px(g,C.leaf7,ri(2,10),ri(9,13),4,2); }
    return c; });
  { const [c,g]=mk(T,T); px(g,C.leaf7,2,0,12,T); px(g,C.leaf6,4,0,3,T); px(g,C.leaf5,5,0,1,T); px(g,C.ink,2,0,1,T); px(g,C.ink,13,0,1,T); px(g,C.leaf8,10,0,2,T); TILE.column=c; }
  { const [c,g]=mk(T,T); px(g,C.leaf6,0,4,T,8); px(g,C.leaf5,0,4,T,1); px(g,C.ink,0,12,T,1); px(g,C.leaf7,1,6,14,4); TILE.capital=c; }
  // bamboo bridge (one-way)
  { const [c,g]=mk(T,T); px(g,C.wood,0,0,T,5); px(g,C.papL,0,0,T,1); px(g,C.woodD,0,4,T,2);
    for(let x=3;x<T;x+=4) px(g,C.woodD,x,1,1,3); px(g,C.ivoD,0,2,1,1); px(g,C.woodD,7,6,2,3); TILE.bridge=c; }
  // bone spikes
  { const [c,g]=mk(T,T); for(let i=0;i<4;i++){ const x=i*4; px(g,C.ivoDD,x,13,4,3); px(g,C.ivo,x+1,8,2,6); px(g,C.ivo,x+1,6,1,2); px(g,C.ivoD,x+2,9,1,5); px(g,C.ivo,x+1,5,1,1);} TILE.spikes=c; }
  // animated water: 4 surface frames + body
  TILE.waterTop = [0,1,2,3].map(f=>{ const [c,g]=mk(T,T); px(g,C.water,0,4,T,12); px(g,C.waterD,0,11,T,5);
    for(let x=0;x<T;x++){ const w=((x+f*4)%16); const up = w<5?1:0; px(g,C.waterL,x,4-up,1,1); px(g,C.water,x,5-up,1,1); if(w===9||w===10) px(g,C.waterL,x,8,1,1); }
    px(g,C.ivo,(f*4+2)%16,3,2,1); return c; });
  TILE.waterBody = [0,1].map(f=>{ const [c,g]=mk(T,T); px(g,C.waterD,0,0,T,T); px(g,C.water,(3+f*5)%14,4,3,1); px(g,C.water,(10+f*3)%14,11,2,1); px(g,'#0a3a3c',0,12,T,4); return c; });
})();

