/* ==LEVEL== */
const LW = 96, LH = 12, WORLD_W = LW*T, WORLD_H = LH*T;
const map = [], back = [];
for(let y=0;y<LH;y++){ map.push(new Array(LW).fill(' ')); back.push(new Array(LW).fill(' ')); }
function fill(x0,y0,x1,y1,ch,m){ m=m||map; for(let y=y0;y<=y1;y++) for(let x=x0;x<=x1;x++) m[y][x]=ch; }
const SPAWN = {gems:[], enemies:[], torches:[], vines:[], key:null, door:null, start:{x:2*T,y:9*T}};
(function buildLevel(){
  // --- ground: jungle earth, temple stone in the middle
  fill(0,10,95,11,'G'); fill(24,10,73,11,'#');
  // --- A: jungle approach
  fill(10,9,11,9,'#');
  fill(22,10,23,11,'~');
  // --- B: temple facade + roof + back wall
  fill(28,1,72,9,'w',back); fill(28,0,73,1,'#'); fill(28,2,29,6,'#'); fill(72,2,73,6,'#');
  for(const cx of [35,46,52,61,68]){ fill(cx,3,cx,9,'c',back); back[2][cx]='C'; }
  for(const wx of [31,40,49,56,65]){ fill(wx,4,wx+1,6,' ',back); }
  fill(33,9,33,9,'#'); fill(34,8,40,9,'#');
  fill(37,6,39,6,'-'); fill(42,4,45,4,'-');
  fill(44,9,45,9,'^');
  // --- C: key hall
  fill(54,9,59,9,'#');
  fill(62,10,63,11,'~');
  // --- D: ruins + bridge + exit
  fill(76,9,77,9,'^');
  fill(80,9,80,9,'#'); fill(81,8,82,9,'#');
  fill(83,8,86,8,'-'); fill(83,10,86,11,'~');
  fill(87,8,88,9,'#');
  fill(94,0,95,9,'#');
  // --- things
  const gem=(x,y,k)=>SPAWN.gems.push({x:x*T+4,y:y*T+4,k:k||0});
  [5,6,7].forEach(x=>gem(x,9)); gem(10,7,1); gem(11,7,1);
  gem(22,7); gem(23,7); gem(15,9); gem(18,9);
  [35,36].forEach(x=>gem(x,7)); [37,38,39].forEach(x=>gem(x,5,1)); [42,43,44,45].forEach(x=>gem(x,3,1));
  gem(48,9); gem(50,9); gem(52,9); gem(51,6,1);
  gem(62,7); gem(63,7); gem(66,9); gem(69,9);
  [83,84,85,86].forEach(x=>gem(x,7)); gem(85,4,1); gem(90,9,1);
  SPAWN.key = {x:58*T+2, y:8*T+5};
  SPAWN.door = {x:92*T, y:8*T};
  SPAWN.enemies.push({t:'snake',x:14*T,y:10*T,x0:13*T,x1:20*T});
  SPAWN.enemies.push({t:'snake',x:67*T,y:10*T,x0:65*T,x1:71*T});
  SPAWN.enemies.push({t:'bat',x:50*T,y:6*T,x0:47*T,x1:53*T});
  SPAWN.enemies.push({t:'bat',x:84*T,y:4*T+8,x0:82*T,x1:88*T});
  [[30,6],[38,3],[44,7],[50,4],[58,5],[64,4],[70,6]].forEach(p=>SPAWN.torches.push({x:p[0]*T+8,y:p[1]*T+4}));
  [[4,0,4],[8,0,3],[16,0,5],[20,0,3],[32,2,3],[36,2,2],[43,2,1],[48,2,4],[55,2,3],[60,2,4],[67,2,3],[71,2,2],[75,0,4],[79,0,3],[85,0,2],[90,0,5]]
    .forEach(v=>SPAWN.vines.push({x:v[0]*T+8,y:v[1]*T,len:v[2]*T+ri(0,8),ph:rnd()*6}));
})();
const tileAt=(tx,ty)=> (tx<0||tx>=LW) ? '#' : (ty<0||ty>=LH) ? ' ' : map[ty][tx];
const isSolid=ch=> ch==='#'||ch==='G';

// Pre-render the entire static level once
const [levelCv, lg] = mk(WORLD_W, WORLD_H);
(function paintLevel(){
  for(let y=0;y<LH;y++) for(let x=0;x<LW;x++){
    const b=back[y][x], X=x*T, Y=y*T;
    if(b==='w') lg.drawImage(TILE.wall[(x*7+y*3)%3],X,Y);
    else if(b==='c'){ lg.drawImage(TILE.wall[0],X,Y); lg.drawImage(TILE.column,X,Y); }
    else if(b==='C'){ lg.drawImage(TILE.wall[0],X,Y); lg.drawImage(TILE.capital,X,Y); }
    // arched window frames around wall holes
    if(b===' ' && y>0 && x>0 && x<LW-1 && (back[y][x-1]!==' '||back[y][x+1]!==' ') && y<10){
      if(back[y][x-1]==='w') px(lg,C.leaf6,X,Y,2,T); if(back[y][x+1]==='w') px(lg,C.leaf6,X+14,Y,2,T);
      if(back[y-1][x]==='w'){ px(lg,C.leaf6,X,Y,T,2); px(lg,C.leaf8,X+(back[y][x-1]==='w'?2:0),Y+2,4,2); px(lg,C.leaf8,X+(back[y][x+1]==='w'?10:12),Y+2,4,2); }
      if(back[y+1] && back[y+1][x]==='w') px(lg,C.leaf5,X,Y+14,T,2);
    }
  }
  for(let y=0;y<LH;y++) for(let x=0;x<LW;x++){
    const ch=map[y][x], X=x*T, Y=y*T, up=tileAt(x,y-1);
    if(ch==='#'){ lg.drawImage(TILE.brick[(x*5+y*7+(x*y))%3],X,Y); if(!isSolid(up)&&y>1) lg.drawImage(TILE.moss[x%2],X,Y);
      if(y<=1 && !isSolid(tileAt(x,y+1))) { px(lg,C.stoneDD,X,Y+13,T,3); px(lg,C.ink,X,Y+15,T,1); } }
    else if(ch==='G'){ lg.drawImage(TILE.earth[(x+y)%2],X,Y); if(!isSolid(up)) lg.drawImage(TILE.grass[x%2],X,Y); }
    else if(ch==='-') lg.drawImage(TILE.bridge,X,Y);
    else if(ch==='^') lg.drawImage(TILE.spikes,X,Y);
  }
  // little plants + papaya flowers on grass
