/* ==PLAYER== */
const RUN=95, ACC=900, GRAV=950, JUMP=310, MAXFALL=330;
const P = {x:0,y:0,w:8,h:14,vx:0,vy:0,dir:1,ground:false,coyote:0,jbuf:0,prevJump:false,anim:0,dead:0,inv:0};
function placePlayer(x,y){ P.x=x; P.y=y; P.vx=P.vy=0; P.dir=1; P.dead=0; P.ground=false; P.prevJump=false; P.jbuf=0; }
function movePlayer(dt,inp){
  const want=(inp.right?1:0)-(inp.left?1:0);
  if(want){ P.vx+=want*ACC*dt; P.dir=want; } else { const d=Math.sign(P.vx); P.vx-=d*Math.min(Math.abs(P.vx),ACC*dt); }
  P.vx=clamp(P.vx,-RUN,RUN);
  P.coyote = P.ground ? .09 : P.coyote-dt;
  if(inp.jump && !P.prevJump) P.jbuf=.12; P.prevJump=inp.jump; P.jbuf-=dt;
  if(P.jbuf>0 && P.coyote>0){ P.vy=-JUMP; P.jbuf=0; P.coyote=0; P.ground=false; if(typeof onJump==='function') onJump(); }
  if(!inp.jump && P.vy<-110) P.vy=-110;               // release early = short hop
  P.vy=Math.min(P.vy+GRAV*dt,MAXFALL);
  // horizontal
  P.x+=P.vx*dt;
  { const top=Math.floor(P.y/T), bot=Math.floor((P.y+P.h-.01)/T);
    if(P.vx>0){ const tx=Math.floor((P.x+P.w)/T); for(let ty=top;ty<=bot;ty++) if(isSolid(tileAt(tx,ty))){ P.x=tx*T-P.w-.001; P.vx=0; break; } }
    else if(P.vx<0){ const tx=Math.floor(P.x/T); for(let ty=top;ty<=bot;ty++) if(isSolid(tileAt(tx,ty))){ P.x=(tx+1)*T; P.vx=0; break; } } }
  // vertical (bridges are one-way)
  const prevBottom=P.y+P.h, wasGround=P.ground; P.y+=P.vy*dt; P.ground=false;
  { const l=Math.floor(P.x/T), r=Math.floor((P.x+P.w-.01)/T);
