/* ==ENTITIES== */
let gems=[], enemies=[], keyItem=null, door=null;
let playSfx=function(){}, showToast=function(){}, syncHud=function(){}, endGame=function(kind){ G.mode=kind; };
const CHECKPOINTS=[26,47,74];
// tiny particle pool (hard cap keeps it cheap)
const fx=[]; const FX_MAX=48;
function puff(x,y,n,col,spd,up){ for(let i=0;i<n&&fx.length<FX_MAX;i++){ const a=Math.random()*6.283, s=spd*(.4+Math.random()*.6); fx.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-(up||0),life:.35+Math.random()*.35,c:col,g:up?500:120}); } }
function updateFx(dt){ for(let i=fx.length-1;i>=0;i--){ const p=fx[i]; p.life-=dt; if(p.life<=0){ fx[i]=fx[fx.length-1]; fx.pop(); continue; } p.vy+=p.g*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; } }
function drawFx(cx,cy){ for(const p of fx){ ctx.fillStyle=p.c; const s=p.life>.25?2:1; ctx.fillRect((p.x-cx)|0,(p.y-cy)|0,s,s); } }
function onJump(){ puff(P.x+4,P.y+P.h,4,C.ivoD,30,10); playSfx('jump'); }
function onLand(){ puff(P.x+4,P.y+P.h,5,C.ivoD,36,14); }

function resetLevel(){
  gems=SPAWN.gems.map(g=>({x:g.x,y:g.y,k:g.k,got:false,ph:Math.random()*6}));
  enemies=SPAWN.enemies.map(e=>({t:e.t,x:e.x,y:e.t==='snake'?e.y-8:e.y,y0:e.y,x0:e.x0,x1:e.x1,dir:1,dead:0,ph:Math.random()*6,w:e.t==='snake'?14:12,h:e.t==='snake'?8:7}));
  keyItem={x:SPAWN.key.x,y:SPAWN.key.y,got:false}; door={x:SPAWN.door.x,y:SPAWN.door.y,open:false};
  G.gems=0; G.total=gems.length; G.hasKey=false; G.lives=3; G.winT=0; G.check=-1; G.doorHint=0;
  placePlayer(SPAWN.start.x,SPAWN.start.y); P.inv=0; fx.length=0; followCamera(0,true); syncHud();
}
const hit=(ax,ay,aw,ah,bx,by,bw,bh)=>ax<bx+bw&&ax+aw>bx&&ay<by+bh&&ay+ah>by;
function killPlayer(splash){
  if(P.dead>0||P.inv>0||G.winT>0) return;
  P.dead=1.2; P.vy=splash?-90:-250; P.vx=0; playSfx('hurt');
  puff(P.x+4,P.y+8,10,splash?C.waterL:C.pap,70,40);
  if(G.mode==='play'){ G.lives--; syncHud(); }
}
function afterDeath(){
  if(G.mode==='play' && G.lives<=0){ endGame('over'); return; }
  const c=G.check; placePlayer(c<0?SPAWN.start.x:CHECKPOINTS[c]*T, 9*T+2); P.inv=1.6;
}
function updateEnemies(dt,alive){
  for(const e of enemies){
    if(e.dead>0){ e.dead-=dt; if(e.dead<=0) e.gone=true; continue; } if(e.gone) continue;
    const sp=e.t==='snake'?26:42; e.x+=e.dir*sp*dt; if(e.x<e.x0){ e.x=e.x0; e.dir=1; } if(e.x+e.w>e.x1){ e.x=e.x1-e.w; e.dir=-1; }
    if(e.t==='bat') e.y=e.y0+Math.sin(G.time*2.3+e.ph)*11;
    if(alive && hit(P.x,P.y,P.w,P.h,e.x+1,e.y+1,e.w-2,e.h-1)){
      if(P.vy>40 && P.y+P.h-e.y<9){ e.dead=.35; P.vy=-230; P.inv=Math.max(P.inv,.15); puff(e.x+e.w/2,e.y+4,9,C.papL,60,20); playSfx('stomp'); }
      else killPlayer(false);
    }
  }
}
function checkWorld(){
  // hazards
  const l=Math.floor((P.x+1)/T), r=Math.floor((P.x+P.w-1)/T), by=P.y+P.h, ty=Math.floor((by-1)/T);
  for(let tx=l;tx<=r;tx++){ const ch=tileAt(tx,ty); if(ch==='^'&&by>ty*T+7){ killPlayer(false); return; } if(ch==='~'&&by>ty*T+10){ killPlayer(true); return; } }
  if(P.y>WORLD_H+24){ killPlayer(true); return; }
  // checkpoints
  if(P.ground) for(let i=CHECKPOINTS.length-1;i>G.check;i--) if(P.x>CHECKPOINTS[i]*T){ G.check=i; break; }
  // pickups
  for(const g of gems){ if(!g.got && hit(P.x,P.y,P.w,P.h,g.x-1,g.y-1,10,10)){ g.got=true; G.gems++; puff(g.x+4,g.y+4,6,g.k?C.ivo:C.papL,55,10); playSfx('gem'); syncHud(); } }
  if(!keyItem.got && hit(P.x,P.y,P.w,P.h,keyItem.x,keyItem.y-2,12,9)){ keyItem.got=true; G.hasKey=true; puff(keyItem.x+6,keyItem.y+2,12,C.ivo,70,10); playSfx('key'); showToast('Key found — the exit is unlocked!'); syncHud(); }
  // exit door
  G.doorHint-=1/60;
  if(hit(P.x,P.y,P.w,P.h,door.x+4,door.y+8,8,24)){
    if(G.hasKey){ if(!door.open){ door.open=true; G.winT=.9; P.vx=0; puff(door.x+8,door.y+16,14,C.papL,60,20); playSfx('win'); } }
    else if(G.doorHint<=0){ G.doorHint=3; showToast('Locked! Find the temple key first.'); playSfx('locked'); }
  }
}
function stepGame(dt){
  if(G.mode==='win'||G.mode==='over'){ updateEnemies(dt,false); updateFx(dt); return; }
  const inp=(G.mode==='attract'&&typeof botInput==='function')?botInput(dt):keys;
  if(G.winT>0){ G.winT-=dt; if(G.winT<=0) endGame('win'); }
  else if(P.dead>0){ P.vy+=GRAV*dt; P.y+=P.vy*dt; P.dead-=dt; if(P.dead<=0) afterDeath(); }
  else { movePlayer(dt,inp); checkWorld(); }
  updateEnemies(dt, P.dead<=0 && G.winT<=0); updateFx(dt); followCamera(dt);
  if(P.inv>0) P.inv-=dt;
}
function drawActors(cx,cy,t){
  ctx.drawImage(SP.door[door.open?1:0],door.x-cx,door.y-cy);
  for(const g of gems){ if(g.got) continue; const sx=g.x-cx; if(sx<-12||sx>W+4) continue; const by=Math.round(Math.sin(t*3+g.ph)*1.5);
    ctx.drawImage(SP.gem[g.k],(sx-1)|0,(g.y-cy-1+by)|0); if(((t*1.3+g.ph)%2.2)<.18) ctx.drawImage(SP.spark,(sx+3)|0,(g.y-cy-3+by)|0); }
  if(!keyItem.got){ const by=Math.round(Math.sin(t*2.6)*2); ctx.drawImage(SP.key,(keyItem.x-cx-1)|0,(keyItem.y-cy-1+by)|0); if((t%1.6)<.2) ctx.drawImage(SP.spark,(keyItem.x-cx+8)|0,(keyItem.y-cy-4+by)|0); }
  for(const e of enemies){ if(e.gone) continue; const sx=e.x-cx; if(sx<-24||sx>W+8) continue;
    if(e.dead>0 && ((t*20)|0)%2) continue;
    if(e.t==='snake') ctx.drawImage(SP.snake[(t*6|0)%2][e.dir>0?1:0],(sx-2)|0,(e.y-cy-3+(e.dead>0?3:0))|0);
    else ctx.drawImage(SP.bat[(t*9|0)%2],(sx-3)|0,(e.y-cy-2)|0); }
  if(G.winT<=0 || G.winT>.55) drawPlayer(cx,cy,t);
}
G.mode='play'; resetLevel();

