toolInput.new_string:
canvas#game{
  width:100%; height:100%; display:block;
  image-rendering:crisp-edges; image-rendering:pixelated;
}
body{
  background:
    radial-gradient(120% 80% at 50% 0%, #12382a 0%, transparent 60%),
    radial-gradient(90% 60% at 50% 110%, rgba(226,97,42,.16) 0%, transparent 60%),
    var(--leaf-900);
}
.shell{max-width:1500px}
.top, .pad{width:min(96vw, calc((100vh - 170px) * 16 / 9)); display:flex; align-items:center; justify-content:space-between; gap:12px}
.brand{display:flex; align-items:center; gap:10px; min-width:0}
.leaf{width:14px; height:14px; flex:none; background:var(--papaya); border-radius:0 70% 0 70%; box-shadow:inset -3px -3px 0 var(--papaya-deep)}
h1{font-size:clamp(14px,2.2vw,22px); letter-spacing:.06em; text-transform:uppercase; font-weight:800; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}
h1 em{font-style:normal; color:var(--papaya)}
.pill{
  font:inherit; font-size:12px; letter-spacing:.08em; text-transform:uppercase; color:var(--ivory);
  background:rgba(251,243,223,.06); border:1px solid rgba(251,243,223,.22); border-radius:999px;
  padding:7px 12px; display:inline-flex; align-items:center; gap:8px; cursor:pointer; flex:none;
  transition:background .2s, border-color .2s, transform .15s;
}
.pill:hover{background:rgba(251,243,223,.12); border-color:var(--papaya-soft)}
.pill:active{transform:scale(.96)}
.pill .dot{width:8px; height:8px; border-radius:50%; background:var(--ivory-dim); transition:background .2s, box-shadow .2s}
.pill[aria-pressed="true"] .dot{background:var(--papaya); box-shadow:0 0 0 3px rgba(255,138,61,.25)}
.stage{
  box-shadow:0 0 0 2px #1b4a33, 0 0 0 5px var(--leaf-800), 0 24px 60px -18px rgba(0,0,0,.8);
  touch-action:none; user-select:none; -webkit-user-select:none;
}
.stage::after{ /* soft vignette, one static layer */
  content:""; position:absolute; inset:0; pointer-events:none;
  background:radial-gradient(ellipse at center, transparent 58%, rgba(3,12,8,.5) 100%);
}
.hud{position:absolute; z-index:2; top:2.2%; left:1.6%; right:1.6%; display:flex; gap:1.2%; align-items:center; pointer-events:none}
.chip{
  display:flex; align-items:center; gap:.5em; padding:.35em .7em; font-size:clamp(10px,1.5vw,16px); font-weight:700; letter-spacing:.05em;
  background:rgba(6,21,15,.72); border:1px solid rgba(251,243,223,.18); border-radius:8px; color:var(--ivory);
}
.chip canvas{height:1.1em; width:auto; image-rendering:pixelated}
.chip.lives{margin-left:auto; gap:.3em}
.chip.lives canvas{transition:opacity .25s, transform .25s}
.chip.lives canvas.lost{opacity:.18; transform:scale(.8)}
#keyChip{color:var(--ivory-dim)} #keyChip canvas{opacity:.35; transition:opacity .3s}
#keyChip.has{color:var(--papaya-soft); border-color:var(--papaya)} #keyChip.has canvas{opacity:1}
.bump{animation:bump .25s ease-out}
@keyframes bump{0%{transform:scale(1)}40%{transform:scale(1.14)}100%{transform:scale(1)}}
.demo-tag{
  position:absolute; z-index:2; left:50%; top:2.6%; transform:translateX(-50%); font-size:clamp(9px,1.2vw,13px); letter-spacing:.3em; text-transform:uppercase;
  color:var(--leaf-900); background:var(--papaya); padding:.25em .7em .25em 1em; border-radius:4px; font-weight:800;
}
.prompt{position:absolute; z-index:2; left:0; right:0; bottom:9%; text-align:center; pointer-events:none}
.prompt span{
  display:inline-block; font-size:clamp(11px,1.9vw,20px); font-weight:800; letter-spacing:.16em; text-transform:uppercase;
  color:var(--ivory); background:rgba(6,21,15,.78); border:1px solid var(--papaya); border-radius:8px; padding:.55em 1.1em;
  animation:blink 1.4s steps(2,jump-none) infinite;
}
@keyframes blink{0%{opacity:1}100%{opacity:.45}}
.toast{
  position:absolute; z-index:2; left:50%; bottom:6%; transform:translate(-50%,12px); opacity:0; pointer-events:none; white-space:nowrap;
  font-size:clamp(10px,1.4vw,15px); font-weight:700; color:var(--leaf-900); background:var(--ivory); border-radius:8px; padding:.5em .9em;
  box-shadow:0 3px 0 var(--papaya-deep); transition:opacity .25s, transform .25s;
}
.toast.show{opacity:1; transform:translate(-50%,0)}
.overlay{position:absolute; z-index:3; inset:0; display:flex; align-items:center; justify-content:center; background:rgba(4,14,10,.72); animation:fade .35s ease-out}
.overlay[hidden]{display:none}
.card{
  text-align:center; padding:clamp(14px,3vw,30px) clamp(18px,4vw,44px); border-radius:14px; max-width:86%;
  background:linear-gradient(180deg,#123a29,#0b2318); border:2px solid var(--papaya); box-shadow:0 6px 0 var(--papaya-deep), 0 22px 40px -12px #000;
  animation:pop .4s cubic-bezier(.2,1.4,.4,1);
}
.eyebrow{font-size:clamp(9px,1.2vw,13px); letter-spacing:.3em; text-transform:uppercase; color:var(--papaya-soft)}
.card h2{font-size:clamp(18px,3.6vw,40px); margin:.2em 0 .25em; letter-spacing:.04em; color:var(--ivory)}
.card p{font-size:clamp(10px,1.5vw,16px); color:var(--ivory-dim)}
.card .hint{margin-top:.9em; font-size:clamp(9px,1.1vw,12px); opacity:.7}
.cta{
  margin-top:1em; font:inherit; font-weight:800; font-size:clamp(11px,1.6vw,17px); letter-spacing:.12em; text-transform:uppercase; cursor:pointer;
  color:var(--leaf-900); background:var(--papaya); border:0; border-radius:10px; padding:.7em 1.5em; box-shadow:0 4px 0 var(--papaya-deep);
  transition:transform .12s, box-shadow .12s, background .2s;
}
.cta:hover{background:var(--papaya-soft)} .cta:active{transform:translateY(3px); box-shadow:0 1px 0 var(--papaya-deep)}
@keyframes fade{from{opacity:0}to{opacity:1}}
@keyframes pop{from{transform:scale(.85) translateY(10px); opacity:0}to{transform:none; opacity:1}}
.pad{user-select:none; -webkit-user-select:none}
.pad-group{display:flex; gap:10px}
.pbtn{
  width:clamp(52px,9vw,72px); height:clamp(44px,7vw,56px); border-radius:12px; cursor:pointer; touch-action:none;
  font:inherit; font-weight:800; font-size:12px; letter-spacing:.12em; text-transform:uppercase; color:var(--ivory);
  background:linear-gradient(180deg,#1b4a33,#103424); border:1px solid rgba(251,243,223,.2); box-shadow:0 4px 0 #051009;
  display:flex; align-items:center; justify-content:center; transition:transform .08s, box-shadow .08s, background .15s;
}
.pbtn.jump{width:clamp(84px,14vw,120px); background:linear-gradient(180deg,var(--papaya),var(--papaya-deep)); color:var(--leaf-900); border-color:var(--papaya-soft); box-shadow:0 4px 0 #7a2f12}
.pbtn.on, .pbtn:active{transform:translateY(3px); box-shadow:0 1px 0 #051009}
.tri{width:0; height:0; border:9px solid transparent}
.tri.l{border-right-color:var(--ivory); margin-left:-9px} .tri.r{border-left-color:var(--ivory); margin-right:-9px}
.keys{font-size:11px; color:var(--ivory-dim); letter-spacing:.04em; text-align:center; line-height:1.5}
.keys b{color:var(--ivory); font-weight:700}
button:focus-visible{outline:2px solid var(--papaya-soft); outline-offset:3px}
@media (max-width:620px){ .keys{display:none} .stage{border-radius:6px} .pill span#muteTxt{display:none} .pill{padding:9px} }
@media (max-height:520px) and (orientation:landscape){
  .top{display:none} .shell{padding:4px; gap:0}
  .stage{width:min(100vw, calc(100vh * 16 / 9)); border-radius:0}
  .pad{position:fixed; left:0; right:0; bottom:8px; width:auto; padding:0 12px; z-index:5; pointer-events:none}
  .pad .pbtn{pointer-events:auto; opacity:.8} .keys{display:none}
}
@media (prefers-reduced-motion:reduce){ .prompt span,.card,.overlay,.bump{animation:none} }

