const html=fs.readFileSync('{{PROJECT}}/dave-jungle-temple.html','utf8');
let src=html.match(/<script>([\s\S]*?)<\/script>/)[1];
src=src.replace('/* ==BOOT== */','window.__t={update,P,G,bot,getE:()=>enemies,keyItem:()=>keyItem};');
const bh=new Proxy(function(){},{get:(t,k)=>k===Symbol.toPrimitive?()=>0:bh,apply:()=>bh,set:()=>true,construct:()=>bh});
global.window={}; global.document=bh; global.addEventListener=()=>{}; global.requestAnimationFrame=()=>1; global.cancelAnimationFrame=()=>{};
eval(src);
const {update,P,G,bot}=window.__t;
let lastLog=-1, deaths=0, wasDead=false, wins=0, prevRestart=0;
const maxT=+process.argv[2]||80, fps=+process.argv[3]||60;
for(let i=0;i<maxT*fps;i++){
  update(1/fps);
  if(P.dead>0&&!wasDead){ deaths++; console.log('DEATH t='+G.time.toFixed(2)+' x='+P.x.toFixed(0)+' (tile '+(P.x/16).toFixed(1)+') y='+P.y.toFixed(0)); }
  wasDead=P.dead>0;
  if(bot.restart>0&&prevRestart<=0){ wins++; console.log('WIN t='+G.time.toFixed(2)+' gems='+G.gems+'/'+G.total+' key='+G.hasKey); }
  prevRestart=bot.restart;
  const s=Math.floor(G.time/4); if(s!==lastLog){ lastLog=s; console.log('t='+G.time.toFixed(1)+' tile='+(P.x/16).toFixed(1)+' y='+P.y.toFixed(0)+' gems='+G.gems+' key='+G.hasKey+' mode='+G.mode); }
}
console.log('deaths='+deaths+' wins='+wins);

